package cli

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"time"

	"github.com/spf13/cobra"
)

// enrichOutput represents one enriched record.
type enrichOutput struct {
	Input    string         `json:"input"`
	Kind     string         `json:"kind"` // "rc" | "address"
	RC       string         `json:"rc,omitempty"`
	Data     map[string]any `json:"data,omitempty"`
	Error    string         `json:"error,omitempty"`
	Duration string         `json:"duration_ms,omitempty"`
}

func newEnrichCmd(flags *rootFlags) *cobra.Command {
	var (
		addresses bool
		rateLimit float64
		provincia string
		municipio string
	)
	cmd := &cobra.Command{
		Use:   "enrich",
		Short: "Enriquece RCs o direcciones desde stdin a JSONL con cache + rate-limiting",
		Long: "Lee referencias catastrales (o direcciones, con --addresses) por stdin, una por línea, y emite\n" +
			"un objeto JSON por línea con la property card completa de cada entrada. Cachea respuestas\n" +
			"en disco para evitar re-llamadas costosas. Respeta un rate-limit suave (~5 req/s por defecto).\n\n" +
			"Sustituye los scripts pycatastro de un-solo-uso que cada due-diligence escribe.",
		Example: `  cat refs.txt | catastro-pp-cli enrich --json
  cat addresses.csv | catastro-pp-cli enrich --addresses --provincia MADRID --municipio MADRID`,
		Annotations: map[string]string{
			"mcp:read-only": "true",
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			if dryRunOK(flags) {
				kind := "rc"
				if addresses {
					kind = "address"
				}
				fmt.Fprintf(cmd.OutOrStdout(), `{"would_enrich_kind":%q,"rate":%g}`+"\n", kind, rateLimit)
				return nil
			}
			c, err := flags.newClient()
			if err != nil {
				return err
			}
			scanner := bufio.NewScanner(os.Stdin)
			scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
			interval := time.Second / time.Duration(rateLimit)
			if rateLimit <= 0 {
				interval = 200 * time.Millisecond
			}
			lastCall := time.Time{}

			enc := json.NewEncoder(cmd.OutOrStdout())
			enc.SetIndent("", "")
			for scanner.Scan() {
				line := strings.TrimSpace(scanner.Text())
				if line == "" || strings.HasPrefix(line, "#") {
					continue
				}
				// Rate limit
				elapsed := time.Since(lastCall)
				if elapsed < interval {
					time.Sleep(interval - elapsed)
				}
				lastCall = time.Now()

				out := enrichOutput{Input: line}
				start := time.Now()
				if addresses {
					out.Kind = "address"
					if provincia == "" || municipio == "" {
						out.Error = "addresses mode requires --provincia and --municipio"
					} else {
						parts := strings.Fields(line)
						if len(parts) < 2 {
							out.Error = "address must be 'STREET NUMBER' or 'CL STREET NUMBER'"
						} else {
							sigla, calle, numero := parseAddress(parts)
							params := map[string]string{
								"Provincia": provincia,
								"Municipio": municipio,
								"Sigla":     sigla,
								"Calle":     calle,
								"Numero":    numero,
							}
							data, err := c.Get("/COVCCallejero.svc/json/Consulta_DNPLOC", params)
							if err != nil {
								out.Error = err.Error()
							} else {
								out.Data = parseProperty(data)
								if rc, ok := out.Data["rc"].(string); ok {
									out.RC = rc
								}
							}
						}
					}
				} else {
					out.Kind = "rc"
					out.RC = line
					data, err := c.Get("/COVCCallejero.svc/json/Consulta_DNPRC", map[string]string{"RefCat": line})
					if err != nil {
						out.Error = err.Error()
					} else {
						out.Data = parseProperty(data)
					}
				}
				out.Duration = fmt.Sprintf("%d", time.Since(start).Milliseconds())
				if err := enc.Encode(out); err != nil {
					return err
				}
			}
			return scanner.Err()
		},
	}
	cmd.Flags().BoolVar(&addresses, "addresses", false, "Tratar la entrada como direcciones (default: RCs)")
	cmd.Flags().Float64Var(&rateLimit, "rate", 5.0, "Req/s al servicio OVC (recomendado: 5)")
	cmd.Flags().StringVar(&provincia, "provincia", "", "Provincia para modo addresses")
	cmd.Flags().StringVar(&municipio, "municipio", "", "Municipio para modo addresses")
	return cmd
}

// parseAddress accepts either "CL ALCALA 1" or "ALCALA 1" and returns sigla/calle/numero.
// Common Spanish street sigles: CL, AV, PZ, CR, etc.
func parseAddress(parts []string) (sigla, calle, numero string) {
	// Last part is assumed to be the number
	numero = parts[len(parts)-1]
	knownSiglas := map[string]bool{
		"CL": true, "C": true, "CALLE": true,
		"AV": true, "AVDA": true, "AVENIDA": true,
		"PZ": true, "PLAZA": true,
		"CR": true, "CTRA": true, "CARRETERA": true,
		"PG": true, "PG.": true, "POLIGONO": true,
		"CM": true, "CAMINO": true,
		"PJ": true, "PASAJE": true,
		"GL": true, "GLORIETA": true,
		"RD": true, "RONDA": true,
		"TR": true, "TRAVESIA": true,
		"UR": true, "URB": true, "URBANIZACION": true,
	}
	first := strings.ToUpper(parts[0])
	if knownSiglas[first] {
		sigla = first
		if sigla == "C" {
			sigla = "CL"
		}
		calle = strings.Join(parts[1:len(parts)-1], " ")
	} else {
		sigla = "CL"
		calle = strings.Join(parts[:len(parts)-1], " ")
	}
	return
}

func parseProperty(data json.RawMessage) map[string]any {
	cat := extractCatastroFields(data)
	// Also try to extract RC from DNPLOC envelope
	var env map[string]json.RawMessage
	if json.Unmarshal(data, &env) == nil {
		for _, k := range []string{"consulta_dnplocResult", "consulta_dnprcResult"} {
			if v, ok := env[k]; ok {
				var s map[string]any
				if json.Unmarshal(v, &s) == nil {
					if rc, ok := lookupRC(s); ok {
						cat["rc"] = rc
					}
				}
			}
		}
	}
	return cat
}

func lookupRC(v any) (string, bool) {
	switch t := v.(type) {
	case map[string]any:
		// Common shapes: {"rc":{"pc1":"X","pc2":"Y","car":"Z","cc1":"R","cc2":"E"}}
		if rcMap, ok := t["rc"].(map[string]any); ok {
			return concat(rcMap["pc1"]) + concat(rcMap["pc2"]) + concat(rcMap["car"]) + concat(rcMap["cc1"]) + concat(rcMap["cc2"]), true
		}
		for _, sub := range t {
			if rc, ok := lookupRC(sub); ok {
				return rc, true
			}
		}
	case []any:
		for _, sub := range t {
			if rc, ok := lookupRC(sub); ok {
				return rc, true
			}
		}
	}
	return "", false
}

func concat(v any) string {
	if v == nil {
		return ""
	}
	if s, ok := v.(string); ok {
		return s
	}
	return fmt.Sprintf("%v", v)
}
